/* 
Open the Suggestions tab and choose a template to get started creating different content types for your pop-up. 
To learn more about using Arcade to create pop-up content visit: 
https://developers.arcgis.com/arcade/guide/profiles/#popup-element 
*/

// Get locale
var env = GetEnvironment();
var locale = env['locale'];

// Set variables
var dropOffTitle = IIf(locale!='es', '24-hour ballot drop box', 'Buzón abierto las 24 horas del día');

var dropOffDates = IIf(
  locale != 'es', 
  'Open 6/24 at 8am - 7/21 at 7pm (Arizona/UTC-7)', 
  'desde las 8 de la mañana del 24/6/2026 hasta las 7 de la tarde del 21/7/2026'
  );

return {
  type: 'text',
  text: `
  <dl>
  <dt style="font-weight: bold; font-size: 20px;">${dropOffTitle}</dt>
  <dt style="font-size: 16px;">${dropOffDates}</dt>
  </dl>
  `
}

// Services offered popupElement.fields

// Get locale
var env = GetEnvironment();
var locale = env['locale'];

// Set variables and translate if locale == 'es'
if (locale != 'es') {
  var dropOff = $feature.dropOff;
} else {
  var dropOff = Replace(DomainName($feature, 'dropOff'), 'Yes', 'Sí');
}

var inPerson = '✗ No';

// Build fields element and translate title and labels if locale == 'es'
var servicesFields = {
  type: 'fields',
  title: IIf(locale != 'es', 'Services Offered', 'Servicios Ofrecidos'),
  fieldInfos: [
    {
      fieldName: 'dropOff',
      label: IIf(locale != 'es', 'Ballot Drop-Off', 'Entrega de Boletas')
    },
    {
      fieldName: 'inPerson',
      label: IIf(locale != 'es', 'In-Person Voting', 'Votación en persona')
    }
  ],
  attributes: {
    dropOff: dropOff,
    inPerson: inPerson,
  }
};

// Return fields element
return servicesFields;

// Location information popupElement.fields

// Get locale
var env = GetEnvironment();
var locale = env['locale'];

// Set variables
var address = $feature.address;
var name = $feature.name;
var city = $feature.area;

// Generate map link
var urlSource = 'https://www.google.com/maps/search/?api=1&';
var params = {
  query: name + ' ' + address + ' ' + city
};
var mapLink = urlSource + UrlEncode(params);

// Build fields element and translate title and labels if locale == 'es'
var locationFields = {
  type: 'fields',
  title: IIf(locale != 'es', 'Location Information', 'Información sobre Ubicación'),
  fieldInfos: [
    {
      fieldName: 'name',
      label: IIf(locale != 'es', 'Name', 'Nombre')
    },
    {
      fieldName: 'address',
      label: IIf(locale != 'es', 'Address', 'Dirección')
    },
    {
      fieldName: 'city',
      label: IIf(locale != 'es', 'City/Town', 'Ciudad/Pueblo')
    },
    {
      fieldName: 'mapLink',
      label: IIf(locale != 'es', 'Open in Google Maps', 'Abrir en Google Maps')
    }
  ],
  attributes: {
    name: name,
    address: address,
    city: city,
    mapLink: mapLink
  }
};

// Return fields element
return locationFields;

