// This Arcade content block raises a flag in the pop-up if a VC location is for ballot drop-off only.

// Get locale
var env = GetEnvironment();
var locale = env['locale'];

// Set variables
var textEN = 'This location is for ballot drop-off only. There is no in-person voting at this location.';
var textES = 'En este lugar sólo se pueden entregar boletas. No se puede votar en persona en este lugar.';
var flagText = IIf(locale != 'es', textEN, textES);

var name = $feature.CENTER_NAME;
var dropOffLocations = [
  `Recorder's Main Office`,
  `Recorder's Country Club Office`,
  `Recorder's Eastside Office`
];

if (Includes(dropOffLocations, name)) {
	return { 
	type : 'text', 
	text : '<span style="color:#F2352F;font-weight:bold;">' + flagText + '</span>'
  };
} else {
	null;
}

